# Let me verify this hypothesis: for colors with 2x2 blocks, fill their bounding boxes
def find_and_fill_rectangles(grid):
    H, W = len(grid), len(grid[0])

    # Find all colors with 2x2 blocks
    colors_with_2x2 = set()
    for color in range(10):
        for r in range(H-1):
            for c in range(W-1):
                if (grid[r][c] == color and grid[r+1][c] == color and
                    grid[r][c+1] == color and grid[r+1][c+1] == color):
                    colors_with_2x2.add(color)

    # Create output grid
    output = [[grid[r][c] for c in range(W)] for r in range(H)]

    # For each color with 2x2, fill its bounding box
    for color in colors_with_2x2:
        if color == 0:  # background, skip
            continue

        # Find all cells of this color
        cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == color]

        if not cells:
            continue

        # Bounding box
        min_r, min_c = min(r for r, c in cells), min(c for r, c in cells)
        max_r, max_c = max(r for r, c in cells), max(c for r, c in cells)

        # Fill the bounding box
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if grid[r][c] != color:
                    output[r][c] = color

    return output, colors_with_2x2

